import React from "react";
import { useNavigate, useLocation } from "react-router-dom";
import "./global.css";

export default function PaymentPage() {
  const navigate = useNavigate();
  const location = useLocation();
  const product = location.state?.product;

  if (!product) {
    return <h2 className="center-text">Invalid product.</h2>;
  }

  const handlePayment = (method) => {
    console.log("Payment Selected:", method);

    setTimeout(() => {
      navigate("/thankyou", {
        state: { product, method }
      });
    }, 500);
  };

  return (
    <div className="payment-container">
      <h1>Choose a Payment Method</h1>

      <div className="payment-product-box">
        <img src={product.image} alt="" />
        <h3>{product.title}</h3>
        <p>₹{product.price}</p>
      </div>

      <div className="payment-options">
        <button onClick={() => handlePayment("UPI")}>UPI</button>
        <button onClick={() => handlePayment("Credit / Debit Card")}>Card</button>
        <button onClick={() => handlePayment("Cash on Delivery")}>Cash on Delivery</button>
        <button onClick={() => handlePayment("Net Banking")}>Net Banking</button>
      </div>
    </div>
  );
}
